constexpr size_t budget=32u*1024u*1024u,limit=65536;
auto fields(ScriptAI& a){return std::tie(a.gathering,a.retreating,a.homeOverride,a.defenseHomeOverride,a.policies,a.towns,a.harvesting,a.lumberAssignments,a.assault,a.defenders,a.captain,a.defenderUnits,a.guardUnits,a.suicideUnits,a.retreatPassengers,a.guards,a.guardTicket,a.fillGuards,a.groupTimedLife,a.newHeroes,a.slowChopping,a.captainChanges,a.replacementCount,a.townSpot,a.zeppelinPurchase,a.itemPurchase,a.zeppelinWave,a.transportContinuation,a.zeppelinWaveTicket,a.amphibious,a.pathingDisabled,a.pointAttack,a.randomPaths,a.captainRoute,a.captainRouteTicket,a.commands,a.home,a.defenseHome,a.townHome,a.goal,a.stage,a.allianceTarget,a.enemyBase,a.expansion,a.hero,a.enemyBaseSearch,a.heroLevels,a.nextTick,a.nextItems,a.diagnostics);}
template<size_t... I> void copyFields(ScriptAI& dst,ScriptAI& src,std::index_sequence<I...>){auto a=fields(dst),b=fields(src);((std::get<I>(a)=std::get<I>(b)),...);}
void copyFields(ScriptAI& dst,ScriptAI& src){copyFields(dst,src,std::make_index_sequence<std::tuple_size_v<decltype(fields(dst))>>{});}
std::string sourceDigest(const jass::Module& module){SnapshotWriter out(4u*1024u*1024u);auto& sources=module.program().sources();if(sources.size()>4096)throw std::runtime_error("AI source count exceeds budget");out.size(sources.size());for(auto& source:sources){out.text(source.name,65536);out.text(sha256({reinterpret_cast<const std::uint8_t*>(source.text.data()),source.text.size()}),64);}return sha256(out.finish());}
struct Write {
    static constexpr bool reading=false;SnapshotWriter& out;std::function<std::uint32_t(std::uint32_t)> map;
    size_t count(size_t n){if(n>limit)throw std::runtime_error("AI collection exceeds budget");out.size(n);return n;}
    void word(std::uint32_t& v){out.u32(v);}void integer(int& v){out.u32(std::bit_cast<std::uint32_t>(v));}void wide(std::uint64_t& v){out.u64(v);}void flag(bool& v){out.u32(v);}
    void real(float& v){if(!std::isfinite(v))throw std::runtime_error("Invalid AI real");out.u32(std::bit_cast<std::uint32_t>(v));}void time(double& v){if(!std::isfinite(v))throw std::runtime_error("Invalid AI time");out.u64(std::bit_cast<std::uint64_t>(v));}
    void point(WorldPoint& p){float x=std::bit_cast<float>(p.x.bits()),y=std::bit_cast<float>(p.y.bits());real(x);real(y);}void text(std::string& value){out.text(value,65536);}std::uint32_t key(std::uint32_t id){return id?map(id):0;}void unit(std::uint32_t& id){auto value=key(id);word(value);}
};
struct Read {
    static constexpr bool reading=true;Binary& in;std::function<std::uint32_t(std::uint32_t)> map;
    size_t count(size_t){auto n=in.u32();if(n>limit)throw std::runtime_error("AI collection exceeds budget");return n;}
    void word(std::uint32_t& v){v=in.u32();}void integer(int& v){v=std::bit_cast<int>(in.u32());}void wide(std::uint64_t& v){v=snapshotU64(in);}void flag(bool& v){auto n=in.u32();if(n>1)throw std::runtime_error("Invalid AI flag");v=n!=0;}
    void real(float& v){v=std::bit_cast<float>(in.u32());if(!std::isfinite(v))throw std::runtime_error("Invalid AI real");}void time(double& v){v=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(v))throw std::runtime_error("Invalid AI time");}
    void point(WorldPoint& p){float x=0,y=0;real(x);real(y);p={jass::Real::fromBits(std::bit_cast<std::uint32_t>(x)),jass::Real::fromBits(std::bit_cast<std::uint32_t>(y))};}void text(std::string& value){value=snapshotText(in,65536);}std::uint32_t key(std::uint32_t id){return id?map(id):0;}void unit(std::uint32_t& id){word(id);id=key(id);}
};
template<class A,class T,class F> void sequence(A& a,std::vector<T>& values,F fn){auto n=a.count(values.size());if constexpr(A::reading)values.resize(n);for(auto& value:values)fn(value);}
template<class A,class K,class V,class FK,class FV> void rawMap(A& a,std::map<K,V>& values,FK key,FV value){auto n=a.count(values.size());if constexpr(A::reading){for(size_t i=0;i<n;++i){K k{};V v{};key(k);value(v);if(!values.emplace(k,std::move(v)).second)throw std::runtime_error("Duplicate AI map key");}}else for(auto& [k,v]:values){auto copy=k;key(copy);value(v);}}
template<class A,class V,class F> void unitMap(A& a,std::map<std::uint32_t,V>& values,F value){auto n=a.count(values.size());if constexpr(A::reading){for(size_t i=0;i<n;++i){std::uint32_t key=0;a.unit(key);V v{};value(v);if(!key || !values.emplace(key,std::move(v)).second)throw std::runtime_error("Invalid AI unit map");}}else {std::map<std::uint32_t,V*> sorted;for(auto& [id,v]:values){auto key=a.key(id);if(!key || !sorted.emplace(key,&v).second)throw std::runtime_error("Invalid AI unit mapping");}for(auto [key,v]:sorted){auto stable=key;a.word(stable);value(*v);}}}
template<class A> void unitSet(A& a,std::set<std::uint32_t>& values){auto n=a.count(values.size());if constexpr(A::reading){for(size_t i=0;i<n;++i){std::uint32_t id=0;a.unit(id);if(!id || !values.insert(id).second)throw std::runtime_error("Invalid AI unit set");}}else {std::set<std::uint32_t> sorted;for(auto id:values){auto key=a.key(id);if(!key || !sorted.insert(key).second)throw std::runtime_error("Invalid AI unit mapping");}for(auto key:sorted)a.word(key);}}
template<class A,class T,class F> void optional(A& a,std::optional<T>& value,F fn){bool present=value.has_value();a.flag(present);if constexpr(A::reading){if(present)value.emplace();else value.reset();}if(present)fn(*value);}
template<class A> void strategy(A& a,ScriptAI& ai,jass::Runtime* runtime){
    for(bool* b:{&ai.gathering,&ai.retreating,&ai.homeOverride,&ai.defenseHomeOverride})a.flag(*b);for(auto& b:ai.policies)a.flag(b);sequence(a,ai.towns,[&](auto& id){a.unit(id);});
    rawMap(a,ai.harvesting,[&](int& k){a.integer(k);},[&](auto& v){a.integer(v.first);a.integer(v.second);});unitMap(a,ai.lumberAssignments,[&](auto& v){a.integer(v.town);a.wide(v.revision);});auto counts=[&](auto& m){rawMap(a,m,[&](auto& k){a.word(k);},[&](auto& v){a.word(v);});};counts(ai.assault);counts(ai.defenders);unitSet(a,ai.captain);unitSet(a,ai.defenderUnits);unitSet(a,ai.guardUnits);unitMap(a,ai.suicideUnits,[&](auto& v){a.integer(v);});
    unitMap(a,ai.retreatPassengers,[&](auto& v){a.unit(v.carrier);a.wide(v.passengerRevision);a.wide(v.carrierRevision);a.point(v.returnPoint);a.flag(v.retryReturn);});rawMap(a,ai.guards,[&](auto& k){a.wide(k);},[&](auto& v){a.word(v.type);a.unit(v.unit);a.point(v.point);a.word(v.losses);a.flag(v.filled);a.flag(v.requested);});a.wide(ai.guardTicket);for(bool* b:{&ai.fillGuards,&ai.groupTimedLife,&ai.newHeroes,&ai.slowChopping,&ai.captainChanges})a.flag(*b);a.integer(ai.replacementCount);optional(a,ai.townSpot,[&](auto& v){a.point(v);});
    optional(a,ai.zeppelinPurchase,[&](auto& v){a.unit(v.shop);a.unit(v.buyer);a.time(v.deadline);a.wide(v.revision);});optional(a,ai.itemPurchase,[&](auto& v){a.unit(v.shop);a.unit(v.buyer);a.word(v.item);a.time(v.deadline);a.wide(v.revision);});optional(a,ai.zeppelinWave,[&](auto& v){a.wide(v.ticket);a.point(v.destination);a.time(v.deadline);a.flag(v.departing);unitMap(a,v.passengers,[&](auto& id){a.unit(id);});unitSet(a,v.carriers);auto tickets=[&](auto& m){unitMap(a,m,[&](auto& x){a.wide(x);});};tickets(v.pickupTickets);tickets(v.pickupQueued);tickets(v.carrierRevisions);unitMap(a,v.returnPoints,[&](auto& p){a.point(p);});});optional(a,ai.transportContinuation,[&](auto& v){a.point(v.destination);a.unit(v.target);a.flag(v.awaitingPurchase);});a.wide(ai.zeppelinWaveTicket);
    for(bool* b:{&ai.amphibious,&ai.pathingDisabled,&ai.pointAttack,&ai.randomPaths})a.flag(*b);optional(a,ai.captainRoute,[&](auto& v){a.wide(v.ticket);sequence(a,v.points,[&](auto& p){a.point(p);});unitMap(a,v.members,[&](size_t& index){std::uint64_t wide=std::uint64_t(index);a.wide(wide);if constexpr(A::reading){if(wide>std::numeric_limits<size_t>::max())throw std::runtime_error("AI route index exceeds budget");index=size_t(wide);}});a.flag(v.randomPath);a.unit(v.target);});a.wide(ai.captainRouteTicket);
    auto commands=a.count(ai.commands.size());if constexpr(A::reading){for(size_t i=0;i<commands;++i){int first=0,second=0;a.integer(first);a.integer(second);ai.commands.emplace_back(first,second);}}else for(auto& [first,second]:ai.commands){a.integer(first);a.integer(second);}for(auto* p:{&ai.home,&ai.defenseHome,&ai.townHome,&ai.goal,&ai.stage})a.point(*p);for(auto* id:{&ai.allianceTarget,&ai.enemyBase,&ai.expansion,&ai.hero})a.unit(*id);optional(a,ai.enemyBaseSearch,[&](auto& v){a.unit(v.cursor);a.unit(v.best);a.real(v.distance);});
    auto& value=ai.heroLevels;auto codeType=runtime->module().typeId("code");if constexpr(!A::reading){if(value.text || (value.type!=jass::none && value.type!=codeType) || (value.type==jass::none && value.bits) || (value.bits && (value.codeOwner!=runtime || value.bits-1>=runtime->module().functions().size())) || (!value.bits && value.codeOwner))throw std::runtime_error("Unsupported AI hero code reference");}a.word(value.type);a.word(value.bits);if constexpr(A::reading){if((value.type!=jass::none && value.type!=codeType) || (value.type==jass::none && value.bits) || (value.bits && value.bits-1>=runtime->module().functions().size()))throw std::runtime_error("Invalid AI hero code reference");value.codeOwner=value.bits?runtime:nullptr;}a.time(ai.nextTick);a.time(ai.nextItems);sequence(a,ai.diagnostics,[&](auto& text){a.text(text);});
}
