Bytes ScriptSession::encodeAIState(unsigned owner,const jass::StableHandleMap& encodeHandle) const {
    if(owner>=12 || !ais_[owner] || !runtime_.snapshotSafe() || !ais_[owner]->runtime->snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("AI state snapshot requires a quiescent local session");auto& ai=*ais_[owner];if(ai.owner!=owner)throw std::runtime_error("Invalid AI owner");std::map<std::uint32_t,std::uint32_t> forward,reverse;auto map=[&](std::uint32_t id){if(!encodeHandle || id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=NativeKind::Unit)throw std::runtime_error("Invalid AI unit reference");auto key=encodeHandle("unit",id);auto [x,inserted]=forward.emplace(id,key);auto [y,unique]=reverse.emplace(key,id);if(!key || (!inserted && x->second!=key) || (!unique && y->second!=id))throw std::runtime_error("Invalid AI unit mapping");return key;};SnapshotWriter out(budget-64);out.u32(tag("SAIS"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.u32(owner);out.u32(ai.campaign);out.text(ai.file,65536);out.text(sourceDigest(ai.runtime->module()),64);out.u32(aiPauseDepth_[owner]);ScriptAI copy;copyFields(copy,ai);Write writer{out,map};strategy(writer,copy,ai.runtime.get());return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreAIState(unsigned owner,std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    if(owner>=12 || !ais_[owner] || !runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || aiStateRestored_[owner] || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("AI state restore requires a prepared idle recovery runtime");auto& ai=*ais_[owner];Binary in(openSnapshot(bytes,budget));in.expect(tag("SAIS"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_) || in.u32()!=owner)throw std::runtime_error("AI state map, clock or owner differs");auto campaign=in.u32();if(campaign>1 || bool(campaign)!=ai.campaign || snapshotText(in,65536)!=ai.file || snapshotText(in,64)!=sourceDigest(ai.runtime->module()))throw std::runtime_error("AI state strategy differs");auto paused=in.u32();std::map<std::uint32_t,std::uint32_t> reverse;auto map=[&](std::uint32_t key){if(!decodeHandle)throw std::runtime_error("AI unit mapping missing");auto id=decodeHandle("unit",key);auto [it,unique]=reverse.emplace(id,key);if(!id || !unitIdentityHandles_.contains(key) || unitIdentityHandles_.at(key)!=id || (!unique && it->second!=key))throw std::runtime_error("Invalid AI unit reference mapping");return id;};ScriptAI pending;Read reader{in,map};strategy(reader,pending,ai.runtime.get());in.finish();copyFields(ai,pending);aiPauseDepth_[owner]=paused;aiStateRestored_[owner]=true;
}
